  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Grounded Theory Constant Comparative Analysis",
  "description": "Schema for the output of grouping latent constructs based on Barney Glaser's constant comparative method.",
  "type": "object",
  "properties": {
    "summarized_constructs": {
      "type": "array",
      "description": "A list of new, higher-level latent constructs generated by regrouping the existing ones.",
      "items": {
        "type": "object",
        "required": [
          "label",
          "definition",
          "summarized_ids",
          "theoretical_sampling_criteria"
        ],
        "properties": {
          "label": {
            "type": "string",
            "description": "The name or tag of the new summarizing latent construct."
          },
          "definition": {
            "type": "string",
            "description": "A precise definition of the new construct, derived from the interchangeability of indicators of the grouped items."
          },
          "summarized_ids": {
            "type": "array",
            "description": "The list of IDs of the original constructs that are being grouped into this new construct.",
            "items": {
              "type": "string",
              "description": "ID of the source construct."
            }
          },
          "theoretical_sampling_criteria": {
            "type": "object",
            "description": "Unified inclusion and exclusion criteria for theoretical sampling.",
            "required": [
              "inclusion",
              "exclusion"
            ],
            "properties": {
              "inclusion": {
                "type": "array",
                "description": "A unified list of inclusion criteria derived from the grouped constructs.",
                "items": {
                  "type": "string"
                }
              },
              "exclusion": {
                "type": "array",
                "description": "A unified list of exclusion criteria derived from the grouped constructs.",
                "items": {
                  "type": "string"
                }
              }
            }
          }
        }
      }
    }
  },
  "required": [
    "summarized_constructs"
  ]
}

