antes_metadata = _input.all()
metadata = {}

# FIX 1: Iterate over the correct input list, not the empty dictionary
for papa in antes_metadata: 
    data = papa.json.to_py()
    metadata[data['Nombre del documento']] = data

names = []
for item in _('B').all():
    data = item.json.to_py()
    if "doc_name" in data:
        names.append(data["doc_name"])

segments = _('C').all()
result = {}
current_name_index = 0
previous_segment_num = -1 

for item in segments:
    current_segment_num = item.json.to_py()["metadata"]["segment_number"]

    if current_segment_num < previous_segment_num:
        current_name_index += 1

    if current_name_index < len(names):
        doc_name = names[current_name_index]

        # Initialize the dictionary and a list for the segments
        if doc_name not in result:
            result[doc_name] = {
                "Metadata": None,
                "Segments": []
            }

        content = item.json.to_py()["content"] 

        # FIX 2: Append the content so you don't overwrite previous segments
        result[doc_name]["Segments"].append(content) 

        # FIX 3: Direct dictionary lookup instead of an inefficient loop
        if doc_name in metadata:
            result[doc_name]["Metadata"] = metadata[doc_name] 

    previous_segment_num = current_segment_num

final_output = []
for name, data in result.items():
    # Optional: Add the name inside the object so it's not lost
    data['Document Name'] = name 
    final_output.append(data)

return final_output
